    with pytest.raises(ValueError, match="no prices"):
        average([])

from decimal import Decimal

import pytest

from refproj.pricing import average


def test_average_is_the_arithmetic_mean() -> None:
    assert average([Decimal("1.00"), Decimal("2.00"), Decimal("6.00")]) == Decimal("3.00")


def test_average_of_one_price_is_that_price() -> None:
    assert average([Decimal("19.99")]) == Decimal("19.99")


def test_average_rounds_to_cents() -> None:
    assert average([Decimal("1.00"), Decimal("1.00"), Decimal("2.00")]) == Decimal("1.33")
    assert average([Decimal("1.00"), Decimal("2.00"), Decimal("2.00")]) == Decimal("1.67")


def test_average_rounds_half_up_not_half_even() -> None:
    assert average([Decimal("0.02"), Decimal("0.03")]) == Decimal("0.03")


def test_average_accepts_a_generator() -> None:
    prices = (Decimal(text) for text in ("1.00", "2.00", "6.00"))
    assert average(prices) == Decimal("3.00")


def test_average_of_no_prices_is_rejected() -> None:
    with pytest.raises(ValueError, match="no prices"):
        average([])


def test_average_of_an_empty_generator_is_rejected() -> None:
    with pytest.raises(ValueError, match="no prices"):
        average(Decimal(text) for text in ())


def test_average_does_not_filter_zero_prices() -> None:
    assert average([Decimal("0.00"), Decimal("4.00")]) == Decimal("2.00")
    assert average([Decimal("0.00")]) == Decimal("0.00")


def test_average_counts_every_sale_without_weighting() -> None:
    assert average([Decimal("1.00"), Decimal("1.00"), Decimal("4.00")]) == Decimal("2.00")
